#pragma once

// `segarecomp sega-cd ...` (SEG-062): Sega CD disc inspection and generated-native program emission. Orchestration only; the disc
// reader is libs/media and every machine decision is platforms/sega-cd/machine.
inline constexpr const char *segarecomp_sega_cd_usage =
    "  segarecomp sega-cd inspect --cue <disc.cue> [--expect-identity <sha256>] [--sector-digests] [--iso-tree] [--modules <list>]\n"
    "  segarecomp sega-cd emit --cue <disc.cue> --out <program.c> [--expect-identity <sha256>] [--modules <list>] [--position-independent] [--report-offsets]\n"
    "                              [--aot-policy compatibility|optimized [--aot-model gen2]]  (SEG-097-T003: `optimized` is EXPERIMENTAL for Sega CD - the frozen gen2 M3+B35 proposes which\n"
    "       source-relative regions are compiled; it may omit code and stop at an uncompiled entry; any failure falls back to broad and says why)\n"
    "      (compile <program.c> with platforms/sega-cd/runtime/*.c and platforms/genesis/runtime/{runtime,vdp_render,frame_export}.c;\n"
    "       run it with --disc-dir <dir> --instruction-budget <n>)\n"
    "  segarecomp sega-cd emit --cue <disc.cue> --bios <image> --out <program.c> [--copy-image main|sub:<base>:<rom-offset>:<length>]...\n"
    "                          [--admit epoch:<pass-identity>:<snapshot> | --admit epoch-recipe:<length>:<source>@<dest>[,...] |\n"
    "                           --admit template:<pass-identity>:main|sub:<pc>:<hex>]...\n"
    "                          [--partition-window <bytes>] [--disc-image main|sub:<system-area-offset>:<base>:<length>]...\n"
    "                          [--application-entry <address>] [--file-first all|structural [--file-first-max-bytes <n>] [--file-first-max-offsets <n>] [--jobs <n>]]\n"
    "      (SEG-064 BIOS-image profile, ADR 0142; run it with --bios <image> as well; --materialize-dir <dir> makes a build pass;\n"
    "       --partition-window writes one translation unit per processor PC window next to <program.c>, listed in the report;\n"
    "       --disc-image admits a track-1 extent placed in a processor's RAM as an executable image (SEG-064-T004; main: work RAM\n"
    "       or, SEG-071-T001, the 2M Word RAM view $200000-$23FFFF; sub: PRG RAM);\n"
    "       --file-first (SEG-100, ADR 0221) also compiles, before launch and with no guest base, the disc's ISO9660 files as dynamic images bound at run time;\n"
    "       needs --partition-window;\n"
    "       --application-entry ends the run, with the typed stop application_handoff, at the first main instruction there)\n"
    "  segarecomp sega-cd file-survey --cue <disc.cue> [--expect-identity <sha256>] [--max-file-bytes <n>] [--jobs <n>] [--per-file] [--no-census] [--structural|--structural-open|--structural-faults] [--probe-offsets <file>] [--oracle <file>]\n"
    "      (SEG-100-T001, ADR 0221: aggregate census of the disc's ISO9660 files and of what the CPU-owned decoder and lowering can compile at every even\n"
    "       source offset; counts only; a file larger than --max-file-bytes is reported oversize, never dropped)\n"
    "  segarecomp sega-cd resolve-source --cue <disc.cue> --cpu main|sub --pc <address> --region <file> --region-base <address>\n"
    "                                    [--delivered <first-lba>:<count>[,...]] [--delivered-overflow 1]\n"
    "  segarecomp sega-cd build --cue <disc.cue> --bios <image> --output <dir> --runtime-dir <runtime root> --cc <compiler> [--cc-arg <arg>]...\n"
    "                           [--viewer 1 --sdl3-include <dir> --sdl3-lib <dir>] [--cache-dir <dir>] [--jobs <n>] [--budget <instructions>] [--until-tick <t>]\n"
    "                           [--pass-timeout <seconds>] [--keep-passes 0|1] [--reconstruction 0|1] [--static-producers 0|1] [--static-boot 0|1] [--input-script <file>] [--backup-ram <file>] [--optimize 0|1|2] [--link-arg <arg>]...\n"
    "                           [--aot-policy compatibility|optimized [--aot-model gen2]]   (SEG-097-T003: `optimized` = EXPERIMENTAL frozen gen2 M3+B35 selective proposal; status.json aot_policy)\n"
    "                           [--file-first all|structural [--file-first-max-bytes <n>] [--file-first-max-offsets <n>]]   (SEG-100, ADR 0221: also compile the disc's ISO9660 files before launch as base-less dynamic images, bound at run time; status.json file_first)\n"
    "                           [--static-discovery 0|1] [--static-recursion 0|1] [--static-range hull|loaded]   (SEG-098-T002, ADR 0211: 1 = default, admit the disc modules the static loader scan proves; 0 = the previous build)\n"
    "      (SEG-111, ADR 0255: --reconstruction 0 disables the admission of relocated fragments and produced images, i.e. the previous build; --keep-passes 1 keeps each round's frontier capture)\n"
    "      (SEG-078-T003, ADR 0205: the self-service build - emit, compile, run a build pass, admit the epoch, operand templates and discovered\n"
    "       disc extents, confirm; writes <output>/{program[,program-viewer],status.json,build.log}; progress as @stage/@round/@result lines)\n"
    "  segarecomp sega-cd resolve-source --cue <disc.cue> --cpu main|sub --pc <address> --region <file> --region-base <address>\n"
    "                                    [--delivered <first-lba>:<count>[,...]] [--delivered-overflow 1]\n"
    "      (SEG-078-T003, ADR 0205: find the track-1 span the live RAM window is an exact copy of, among the blocks the build pass's CDC read;\n"
    "       prints the --disc-image extent or a typed refusal; exit 0 resolved, 8 refused)\n"
    "  segarecomp sega-cd discover-producers --cue <disc.cue>\n"
    "      (SEG-112, ADR 0256: recognise counted-copy / byte-transform executable-image producers in the disc's boot images before any code is generated;\n"
    "       prints the proven fragments and aggregate counters; exit 0, 8 on a disc without a usable boot area)\n"
    "  segarecomp sega-cd boot-contract --cue <disc.cue> --bios <image> [--boot-fixture-profiles 1 (tests only: honour a project fixture BIOS tag; assumed, never verified)]\n"
    "      (SEG-113, ADR 0257: the executable boot images the BIOS places in RAM before the application runs, derived from a verified BIOS profile and the\n"
    "       disc alone - the main boot area and the sub boot program - as `static-boot:` admissions; an unverified BIOS or header form yields none, never a guess;\n"
    "       prints the profile, the refusal and the images; exit 0, 8 on an unreadable disc or BIOS)\n"
    "  segarecomp sega-cd derive-relocation --cue <disc.cue> --capture <capture.json> --region <file> --pass <program identity>\n"
    "                                       [--extent <cpu>:<track-1 offset>:<base>:<length>]... [--snapshot <file>]\n"
    "      (SEG-111, ADR 0255: explain a RAM frontier no exact disc span explains from the build pass's bounded write streams: a verified copy of\n"
    "       bytes inside an admitted extent (prints the `extent:` coordinates) or, with --snapshot, bytes a verified producer computed (writes them;\n"
    "       prints the `produced:` coordinates); a typed refusal otherwise; exit 0 derived, 8 refused)\n"
    "  segarecomp sega-cd discover-modules --cue <disc.cue> [--out <modules.txt>] [--module-table-roots] [--computed-call-whatif] [--constant-dispatch] [--work-state] [--recursive-modules] [--state-convergence [--widen-after <n>]] [--static-extents <file> [--static-scope hull|loaded]]\n"
    "      (SEG-097-T001, ADR 0206: static discovery of disc-loaded modules from the sub boot image's own CD-load operations, including modules\n"
    "       no run has loaded; writes the module list admitted by `emit --modules`; prints the typed report; exit 0 found, 9 none or incomplete)\n";

int segarecomp_sega_cd_command(int argc, char **argv);
// SEG-078-T003: `segarecomp sega-cd build` (sega_cd_build.cpp).
int segarecomp_sega_cd_build(int argc, char **argv);
